/* ZHARFA: THE REALM — global namespace + event bus + helpers.
   Everything hangs off window.ZR so modules stay decoupled and
   future modules (backend, cloud save, multiplayer) can plug in via ZR.bus. */
window.ZR = { games:{}, ui:{}, data:{}, sys:{} };
ZR.bus = (() => {
  const h = {};
  return {
    on:(e,f)=>((h[e]=h[e]||[]).push(f)),
    emit:(e,p)=>(h[e]||[]).slice().forEach(f=>{try{f(p)}catch(err){console.error(e,err)}})
  };
})();
ZR.$ = s => document.querySelector(s);
ZR.$$ = s => [...document.querySelectorAll(s)];
ZR.h = (html) => { const d=document.createElement('div'); d.innerHTML=html.trim(); return d.firstElementChild; };
ZR.rand = (a,b) => Math.floor(Math.random()*(b-a+1))+a;
ZR.shuffle = a => { a=[...a]; for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];} return a; };
ZR.wait = ms => new Promise(r=>setTimeout(r,ms));

;
/* Bilingual text. Data files use {fa:"…",en:"…"} objects; UI strings live here. */
ZR.lang = () => ZR.state?.S?.settings?.lang || 'fa';
ZR.L = o => o==null ? '' : (typeof o==='string' ? o : (o[ZR.lang()] ?? o.fa));
ZR.n = v => (typeof v!=='number') ? v : (ZR.lang()==='fa' ? v.toLocaleString('fa-IR') : v.toLocaleString('en-US'));
