ZR.ui.comingSoon = () => new Promise(res=>{ const c=ZR.$('#cutscene'); c.className='on play';
  c.innerHTML=`<div class="cs-bg" style="background-image:url(assets/gate.webp)"></div><div class="soon fadein"><div class="soon-line"></div><small>CHAPTER III · هفت نگهبان</small><h1>COMING SOON</h1><p>${ZR.lang()==='fa'?'ستاره‌ی سیاه صدا می‌زند. معبد غرق‌شده، کوره‌ی اخگر و رصدخانه‌ی تیشتر به‌زودی گشوده می‌شوند. تا آن زمان، آزمون‌ها و مأموریت‌های روزانه منتظرت هستند.':'The black star is calling. The Sunken Temple, the Ember Forge and Tishtar\'s Observatory open soon. Until then, trials and daily quests await.'}</p><div class="soon-line"></div><img src="assets/logo.webp" class="soon-logo"><button class="btn-gold" id="soonOk">${ZR.t('back')}</button></div>`;
  ZR.sfx('gate'); c.querySelector('#soonOk').onclick=()=>{ c.className=''; c.innerHTML=''; res(); }; });

ZR.ui.frame = () => (ZR.data.frames.find(f=>f.id===ZR.state.S.frame)||ZR.data.frames[0]).c;
ZR.ui.av = id => `assets/av_${id}.webp`;
ZR.ui.npcChip = n => { const c=ZR.data.npcs[n], known=ZR.state.S.known.includes(n);
  return `<button class="npc" data-talk="${n}"><img src="${c.img}"><b>${ZR.L(c.name)}</b><small>${ZR.L(c.role)}</small><i>💬</i></button>`; };

;
/* Dialogue tree runner: typewriter lines, then choices. Returns a promise resolved on close. */
ZR.ui.talk = npcId => new Promise(res=>{
  const npc=ZR.data.npcs[npcId], S=ZR.state.S;
  ZR.ui.sheet.close(); ZR.ui.talking=true;
  if(!S.known.includes(npcId)){ S.known.push(npcId); ZR.state.save(); ZR.bus.emit('known',npcId); }
  if(npcId==='shadow'){ S.flags.shadowMeet=(S.flags.shadowMeet||0)+1; ZR.state.save(); }
  const d=ZR.$('#dialog'); d.className='on';
  d.innerHTML=`<div class="dlg ${npcId==='shadow'?'shadowy':''}"><img class="dlg-portrait" src="${npc.img}" alt=""><div class="dlg-box">
    <div class="dlg-head"><span class="dlg-name">${ZR.L(npc.name)}</span><span class="dlg-mood">${ZR.L(npc.role)} · ${ZR.L(npc.mood)}</span></div>
    <p class="dlg-text"></p><div class="dlg-choices"></div><div class="dlg-next">${ZR.t('tapContinue')} ▾</div></div></div>`;
  const p=d.querySelector('.dlg-text'), ch=d.querySelector('.dlg-choices'), nx=d.querySelector('.dlg-next');
  let node, lines, li, typing=null, waitingChoice=false;
  const resolve=l=>ZR.L(typeof l==='function'?l(S):l);
  const go=id=>{ if(id==='end'||!npc.nodes[id]) return close(); node=npc.nodes[id]; if(node.fx) node.fx(S); lines=node.say||[]; li=0; ch.innerHTML=''; waitingChoice=false; line(); };
  const line=()=>{ const txt=resolve(lines[li]); p.textContent=''; let k=0; clearInterval(typing); nx.style.visibility='hidden';
    typing=setInterval(()=>{ p.textContent=txt.slice(0,++k); if(k%3===0)ZR.sfx('text'); if(k>=txt.length) finishLine(); },20); };
  const finishLine=()=>{ clearInterval(typing); typing=null; p.textContent=resolve(lines[li]);
    if(li===lines.length-1 && node.choices){ showChoices(); } else nx.style.visibility='visible'; };
  const showChoices=()=>{ waitingChoice=true; nx.style.visibility='hidden';
    const opts=node.choices.filter(c=>!c.if||c.if(S));
    ch.innerHTML=opts.map((c,i)=>`<button data-c="${i}">${ZR.lang()==='fa'?'◂':'▸'} ${ZR.L(c.t)}</button>`).join('');
    ch.querySelectorAll('[data-c]').forEach(b=>b.onclick=e=>{ e.stopPropagation(); const c=opts[+b.dataset.c]; ZR.sfx('choice'); if(c.fx) c.fx(S); go(c.go); }); };
  const next=()=>{ if(waitingChoice) return; if(typing){ finishLine(); return; }
    if(li<lines.length-1){ li++; ZR.sfx('soft'); return line(); }
    if(node.choices) return showChoices();
    if(node.next) return go(node.next);
    close(); };
  const close=()=>{ clearInterval(typing); d.className=''; d.innerHTML=''; d.onclick=null; ZR.ui.talking=false; ZR.ui.refresh(); res(); ZR.story.run(); };
  d.onclick=next; ZR.sfx('open');
  go(npc.start(S));
});

;
/* Cinematic opening: dark → ZHARFA logo → the gate → narration → name/avatar → city. */
ZR.ui.intro = () => {
  const i=ZR.$('#intro'); i.className='on dark'; const fa=ZR.lang()==='fa';
  const scenes=[
    {cls:'logo', html:`<img src="assets/logo.webp" class="intro-logo"><div class="studio">ZHARFA STUDIO</div><div class="presents">${fa?'تقدیم می‌کند':'presents'}</div>`},
    {cls:'gate', html:`<div class="cine-title big fa-title">${fa?'قلمرو گمشده':'THE LOST REALM'}<span>${fa?'THE LOST REALM':'قلمرو گمشده'}</span></div>`},
    {cls:'gate', html:`<p class="cine-text">${fa?'به قلمرو نِکسار خوش آمدی.':'Welcome to the Realm of Nexar.'}</p>`},
    {cls:'gate', html:`<p class="cine-text">${fa?'اینجا هر چیزی که می‌بینی، بخشی از یک راز قدیمی است.':'Everything you see here is part of an ancient secret.'}</p>`},
    {cls:'gate', html:`<p class="cine-text small">${ZR.L(ZR.data.lore.prologue.text)}</p>`}
  ];
  let k=0;
  const bg=`<div class="intro-bg"></div><div class="intro-glow"></div><div class="intro-glow gold"></div>`;
  const skip=`<button class="skip" id="skip">${ZR.t('skip')} ⏭</button>`;
  const play=()=>{ const s=scenes[k];
    i.className='on '+s.cls; i.innerHTML=bg+`<div class="cine fadein">${s.html}<div class="cine-hint">${ZR.t('tapContinue')}</div></div>`+skip;
    if(k===1){ ZR.sfx('gate'); ZR.audio.setMood('story'); ZR.audio.startMusic(); } else ZR.sfx('whoosh');
    i.querySelector('#skip').onclick=e=>{e.stopPropagation(); create();}; };
  i.onclick=()=>{ if(!i.querySelector('.cine-hint')) return; k++; k<scenes.length?play():create(); };
  i.innerHTML=`<div class="cine"><img src="assets/logo.webp" class="intro-logo dim"><button class="btn-gold" id="begin">${fa?'آغاز':'Begin'}</button><div class="langpick"><button data-l="fa" class="${fa?'on':''}">فارسی</button><button data-l="en" class="${fa?'':'on'}">English</button></div></div>`;
  i.querySelectorAll('[data-l]').forEach(b=>b.onclick=e=>{e.stopPropagation(); ZR.state.S.settings.lang=b.dataset.l; ZR.state.save(); ZR.ui.applyDir(); ZR.ui.intro();});
  i.querySelector('#begin').onclick=e=>{e.stopPropagation(); play();};

  function create(){ i.onclick=null; const S=ZR.state.S; if(!S.avatar)S.avatar='g1';
    i.className='on gate'; i.innerHTML=bg+`<div class="create fadein"><h2>${ZR.t('chooseName')}</h2>
      <input id="nm" maxlength="16" placeholder="${ZR.t('namePh')}" value="${S.name||''}" autocomplete="off">
      <h3>${ZR.t('chooseFace')}</h3><div class="avs">${ZR.data.avatars.map(a=>`<button data-av="${a.id}" class="${S.avatar===a.id?'on':''}"><img src="${ZR.ui.av(a.id)}"></button>`).join('')}</div>
      <button class="btn-gold big" id="go">${ZR.t('enterRealm')}</button></div>`;
    i.querySelectorAll('[data-av]').forEach(b=>b.onclick=()=>{S.avatar=b.dataset.av; i.querySelectorAll('[data-av]').forEach(x=>x.classList.toggle('on',x===b)); ZR.sfx('soft');});
    i.querySelector('#go').onclick=()=>{ const inp=i.querySelector('#nm'), n=inp.value.trim(); if(!n){inp.classList.add('shake');ZR.ui.toast(ZR.t('needName'));setTimeout(()=>inp.classList.remove('shake'),500);return;}
      S.name=n; ZR.state.save(); ZR.sfx('gate'); i.classList.add('out');
      setTimeout(()=>{ i.className=''; i.innerHTML=''; ZR.sys.progress.addLore('prologue'); ZR.ui.enterWorld(true); },1200); };
  }
};

;
ZR.ui.hud = () => { const S=ZR.state.S, need=ZR.sys.progress.need(S.lv);
  ZR.$('#hud').innerHTML=`<button class="me" data-tab="profile"><img src="${ZR.ui.av(S.avatar)}" style="border-color:${ZR.ui.frame()};box-shadow:0 0 12px ${ZR.ui.frame()}">
   <div><b>${S.name}</b><div class="lvrow"><em>${ZR.t('lv')} ${ZR.n(S.lv)}</em><div class="xpb"><i style="width:${S.xp/need*100}%"></i></div><em class="xpn">${ZR.n(S.xp)}/${ZR.n(need)}</em></div></div></button>
   <div class="hud-r"><span class="coins">🪙 ${ZR.n(S.coins)}</span><button class="round sm" data-act="snd" aria-label="sound">${S.settings.snd||S.settings.mus?'🔊':'🔇'}</button></div>`; };
ZR.ui.nav = () => { const tabs=[['home','🏛️'],['world','🗺️'],['games','🎮'],['quests','📜'],['profile','👤']];
  const q=ZR.sys.quests.active().length+(ZR.sys.daily?ZR.sys.daily.ready():0);
  ZR.$('#nav').innerHTML=tabs.map(([k,i])=>`<button data-tab="${k}" class="${ZR.ui.tab===k?'on':''}"><span>${i}</span><small>${ZR.t(k)}</small>${k==='quests'&&q?`<i class="dot">${ZR.n(q)}</i>`:''}</button>`).join(''); };

;
/* The living Central City — an explorable scene with interactive hotspots. */
ZR.ui.coreLevel = () => { const S=ZR.state.S, main=Object.keys(ZR.data.quests).filter(k=>ZR.data.quests[k].main); return main.filter(k=>S.quests[k]?.status==='done').length/main.length; };
ZR.ui.objective = () => { const id=ZR.sys.quests.mainActive(); if(!id) return '';
  const q=ZR.data.quests[id], p=ZR.sys.quests.progress(id), ch=ZR.data.chapterOf(id);
  return `<button class="objective" data-go="${q.go}"><div class="obj-ic">◈</div><div class="obj-b"><small>${ZR.t('chapter')} ${ch.num} · ${ZR.t('currentObj')}</small><b>${ZR.L(q.title)}</b><p>${ZR.L(q.desc)}${p?` <em>(${ZR.n(p[0])}/${ZR.n(p[1])})</em>`:''}</p></div><span class="obj-go">${ZR.t('go')}</span></button>`; };

ZR.ui.hotspotState = h => { const S=ZR.state.S;
  if(h.region){ const r=ZR.data.region(h.region); return ZR.sys.progress.isUnlocked(r)?'open':'locked'; } return 'open'; };
ZR.ui.questTarget = () => { const id=ZR.sys.quests.mainActive(); return id?ZR.data.quests[id].go:null; };

ZR.ui.cityView = () => { const S=ZR.state.S, core=ZR.ui.coreLevel(), tgt=ZR.ui.questTarget(), ch=ZR.data.currentChapter();
  return `<section class="cityview">
   <div class="city-stage" style="--core:${.25+core*.75}">
    <div class="city-img"></div>
    <div class="core-halo"></div><div class="beam"></div>
    <div class="holo h1"></div><div class="holo h2"></div>
    <div class="flag f1"></div><div class="flag f2"></div>
    <div class="mist m1"></div><div class="mist m2"></div>
    <div class="chapter-tag"><small>CHAPTER ${ch.num}</small><b>${ZR.L(ch.title)}</b></div>
    ${ZR.data.hotspots.filter(h=>!h.if||h.if(S)).map((h,i)=>{ const st=ZR.ui.hotspotState(h), here=(h.region||h.id)===tgt||(tgt==='city'&&h.id==='plaza');
      return `<button class="hs ${st} ${here?'target':''} ${h.kind==='shadow'?'ghost':''}" data-hs="${h.id}" style="--x:${h.x}%;--y:${h.y}%;--d:${i*.37}s">
        <span class="hs-dot">${st==='locked'?'🔒':h.icon}</span><span class="hs-lbl">${ZR.L(h.name)}</span></button>`; }).join('')}
    <div class="city-hint">${ZR.t('tapExplore')}</div>
   </div>
   <div class="city-bottom">${ZR.ui.episodeBanner()}${ZR.ui.objective()}</div>
  </section>`; };

ZR.ui.openHotspot = id => { const h=ZR.data.hotspots.find(x=>x.id===id), S=ZR.state.S, tgt=ZR.ui.questTarget();
  ZR.sfx('soft');
  const qline = (goId)=>{ const q=ZR.sys.quests.active().find(k=>ZR.data.quests[k].go===goId); return q?`<div class="sheet-quest"><small>📜 ${ZR.t('questLine')}</small><b>${ZR.L(ZR.data.quests[q].title)}</b><p>${ZR.L(ZR.data.quests[q].desc)}</p></div>`:''; };
  if(h.kind==='shadow'){ return ZR.ui.talk('shadow'); }
  if(h.kind==='core'){ const c=ZR.ui.coreLevel(), pct=Math.round(c*100);
    const state = c<.2?T("سرد و خاموش. فقط رگه‌هایی کم‌رنگ از نور در ترک‌هایش دیده می‌شود.","Cold and dark. Only faint veins of light show in its cracks.")
      : c<.6?T("گرمایی آرام در آن جریان دارد. گاهی مثل قلبی خسته می‌تپد.","A quiet warmth flows through it. Sometimes it beats like a tired heart.")
      : T("نورش به شهر برمی‌گردد. چیزی در درونش بیدار شده.","Its light returns to the city. Something inside has awakened.");
    return ZR.ui.sheet.open(`<div class="sheet-hero core-hero"><div class="core-gem" style="--p:${.25+c*.75}"></div></div>
      <small class="sheet-tag">THE NEXA CORE</small><h2>${ZR.L(h.name)}</h2><p class="sheet-desc">${ZR.L(state)}</p>
      <div class="core-meter"><span>${ZR.lang()==='fa'?'نیروی هسته':'Core power'}</span><div><i style="width:${pct}%"></i></div><em>${ZR.n(pct)}٪</em></div>
      <div class="sheet-acts"><button class="btn-ghost" data-tab="quests">📜 ${ZR.t('chapters')}</button><button class="btn-ghost" data-act="codex">📚 ${ZR.t('codexT')}</button></div>`); }
  if(h.kind==='plaza'){ const bless=Date.now()-S.lastBlessing>=864e5;
    return ZR.ui.sheet.open(`<div class="sheet-hero"><img src="assets/isl_citadel.webp"></div><small class="sheet-tag">CENTRAL PLAZA</small><h2>${ZR.L(h.name)}</h2>
      <p class="sheet-desc">${ZR.lang()==='fa'?'قلب شهر. چشمه‌ای فیروزه‌ای در مرکز میدان هنوز آرام می‌جوشد و مردم دور آن جمع می‌شوند.':'The heart of the city. A turquoise fountain still bubbles softly at its center, and people gather around it.'}</p>
      ${qline('city')}<div class="npcs">${ZR.data.regionNpcs(ZR.data.region('city')).filter(n=>n!=='guard').map(ZR.ui.npcChip).join('')}</div>
      <div class="acts">
       <button class="act" data-act="bless" ${bless?'':'data-dim="1"'}><span>⛲</span><div><b>${ZR.t('blessing')}</b><small>${bless?ZR.t('blessingD'):ZR.t('blessingWait')}</small></div></button>
       <button class="act" data-search="city"><span>🔍</span><div><b>${ZR.t('search')}</b><small>${S.searched.includes('city')?ZR.t('searched'):(ZR.lang()==='fa'?'لبه‌ی چشمه چیزی برق می‌زند…':'Something glints on the fountain rim…')}</small></div></button>
      </div>`); }
  if(h.kind==='gate'){
    return ZR.ui.sheet.open(`<div class="sheet-hero wide" style="background-image:url(assets/gate.webp)"></div><small class="sheet-tag">MAIN GATE</small><h2>${ZR.L(h.name)}</h2>
      <p class="sheet-desc">${ZR.lang()==='fa'?'دروازه‌ای که تو را به قلمرو راه داد. گاوهای بالدار سنگی هنوز با چشمانی فیروزه‌ای نگهبانی می‌دهند.':'The gate that let you into the Realm. Winged stone bulls still keep watch with turquoise eyes.'}</p>
      ${qline('gate')}<div class="npcs">${ZR.ui.npcChip('guard')}</div>`); }
  // region hotspot
  const r=ZR.data.region(h.region), open=ZR.sys.progress.isUnlocked(r);
  if(!open) return ZR.ui.sheet.open(`<div class="sheet-hero"><img src="${r.img}" class="fogged"></div><small class="sheet-tag">${r.tag}</small><h2>${ZR.L(h.name)}</h2>
      <p class="sheet-desc">${ZR.lang()==='fa'?'مه غلیظی راه را پوشانده. هنوز نمی‌توانی از آن بگذری.':'Thick fog covers the way. You cannot pass yet.'}</p><div class="lockbox">🔒 ${ZR.sys.progress.lockReason(r)}</div>${qline(r.id)}`);
  const npcs=ZR.data.regionNpcs(r);
  ZR.ui.sheet.open(`<div class="sheet-hero"><img src="${r.img}"></div><small class="sheet-tag" style="color:${r.color}">${r.tag}</small><h2>${ZR.L(r.name)}</h2>
    <p class="sheet-desc">${ZR.L(r.desc)}</p>${qline(r.id)}
    ${npcs.length?`<div class="npcs">${npcs.map(ZR.ui.npcChip).join('')}</div>`:''}
    ${r.games.length?`<div class="mini-games">${r.games.map(g=>`<span title="${ZR.L(ZR.games[g].name)}">${ZR.games[g].icon}</span>`).join('')}</div>`:''}
    <button class="btn-gold big" data-region="${r.id}">${ZR.t('enter')} ${ZR.L(r.name)}</button>`);
};

;
/* Codex: Characters · Locations · Artifacts · Lore · Chapters. Unknown entries show ??? */
ZR.ui.openCodex = (tab='lore') => { const S=ZR.state.S, U=`<span class="unk">${ZR.t('unknown')}</span>`;
  const tabs=[['characters','👥'],['locations','🗺️'],['artifacts','🗝️'],['loreT','📜'],['chapters','📖']];
  const body={
    characters:()=>Object.entries(ZR.data.npcs).map(([k,n])=>S.known.includes(k)
      ?`<div class="cx-row"><img src="${n.img}"><div><b>${ZR.L(n.name)}</b><small>${ZR.L(n.role)} · ${ZR.L(n.mood)}</small><p>${ZR.L(n.bio)}</p>${S.rep[k]?`<em>${ZR.t('rep')}: ${S.rep[k]>0?'▲':'▼'} ${ZR.n(Math.abs(S.rep[k]))}</em>`:''}</div></div>`
      :`<div class="cx-row unknown"><div class="cx-q">?</div><div>${U}<small>${ZR.t('notMet')}</small></div></div>`).join(''),
    locations:()=>ZR.data.regions.map(r=>S.visited.includes(r.id)
      ?`<div class="cx-row"><img src="${r.img}" class="isl"><div><b>${ZR.L(r.name)}</b><small>${r.tag}</small><p>${ZR.L(r.desc)}</p></div></div>`
      :`<div class="cx-row unknown"><div class="cx-q">?</div><div>${U}<small>${ZR.t('notVisited')}</small></div></div>`).join(''),
    artifacts:()=>Object.entries(ZR.data.items).filter(([,i])=>i.story).map(([k,i])=>S.found.includes(k)
      ?`<div class="cx-row"><div class="cx-ic">${i.icon}</div><div><b>${ZR.L(i.name)}</b><p>${ZR.L(i.desc)}</p></div></div>`
      :`<div class="cx-row unknown"><div class="cx-q">?</div><div>${U}<small>${ZR.t('notFound')}</small></div></div>`).join(''),
    loreT:()=>Object.entries(ZR.data.lore).map(([k,l])=>S.lore.includes(k)
      ?`<button class="cx-row lore" data-lore="${k}"><div class="cx-ic">📜</div><div><b>${ZR.L(l.title)}</b><p>${ZR.L(l.text).slice(0,70)}…</p></div></button>`
      :`<div class="cx-row unknown"><div class="cx-q">?</div><div>${U}</div></div>`).join(''),
    chapters:()=>ZR.ui.chapterList()
  };
  const key=tab==='lore'?'loreT':tab;
  const count={characters:[S.known.length,Object.keys(ZR.data.npcs).length],locations:[S.visited.length,ZR.data.regions.length],artifacts:[S.found.filter(k=>ZR.data.items[k]?.story).length,Object.values(ZR.data.items).filter(i=>i.story).length],loreT:[S.lore.length,Object.keys(ZR.data.lore).length]};
  const html=`${ZR.ui.backBar('📚 '+ZR.t('codexT'), ZR.lang()==='fa'?'هر چه در قلمرو کشف کرده‌ای':'Everything you have discovered')}
    <div class="cx-tabs">${tabs.map(([k,i])=>`<button data-cx="${k}" class="${k===key?'on':''}">${i}<small>${ZR.t(k)}</small>${count[k]?`<em>${ZR.n(count[k][0])}/${ZR.n(count[k][1])}</em>`:''}</button>`).join('')}</div>
    <div class="cx-body">${body[key]()}</div>`;
  const o=ZR.$('#overlay'); if(o.classList.contains('codex-ov')){ o.querySelector('.ov-inner').innerHTML=html; ZR.sfx('soft'); } else ZR.ui.overlay.open(html,'codex-ov');
};
ZR.ui.chapterList = () => { const S=ZR.state.S;
  return ZR.data.chapters.map(c=>{ const done=c.quests.length&&c.quests.every(q=>S.quests[q]?.status==='done'), started=c.quests.some(q=>S.quests[q]);
    const st=!c.playable?'locked':done?'done':started?'active':'locked';
    return `<div class="chap ${st}"><div class="chap-num">${c.num}</div><div class="chap-b"><small>CHAPTER ${c.num} · ${st==='done'?ZR.t('completeCh'):st==='active'?ZR.t('inProgress'):ZR.t('lockedCh')}</small>
      <b>${ZR.L(c.title)}</b><p>${!c.playable?ZR.t('comingSoon'):st==='locked'?ZR.t('comingSoon'):ZR.L(c.blurb)}${c.partial&&c.playable?` <em>(${ZR.lang()==='fa'?'بخش اول':'part one'})</em>`:''}</p>
      ${c.quests.length&&st!=='locked'?`<div class="chap-q">${c.quests.map(q=>`<i class="${S.quests[q]?.status||''}"></i>`).join('')}</div>`:''}</div></div>`; }).join(''); };

;
ZR.ui.tab='home';
ZR.ui.screens = {
 home(){ return ZR.ui.cityView(); },

 world(){ const S=ZR.state.S;
  const links=[['city','arcade'],['city','archive'],['city','treasury'],['city','ruins'],['city','arena'],['city','hall'],['ruins','mystic'],['archive','mystic']];
  const pos=id=>ZR.data.region(id), tgt=ZR.ui.questTarget();
  return `<section class="worldmap"><div class="wm-head"><small>THE LOST REALM</small><h1>${ZR.lang()==='fa'?'نقشه‌ی قلمرو':'Map of the Realm'}</h1></div>
   <div class="wm">
    <svg class="wm-links" viewBox="0 0 100 100" preserveAspectRatio="none">${links.map(([a,b])=>{const A=pos(a),B=pos(b),open=ZR.sys.progress.isUnlocked(B);return `<line x1="${A.x}" y1="${A.y}" x2="${B.x}" y2="${B.y}" class="${open?'open':''}"/>`;}).join('')}</svg>
    ${ZR.data.regions.map((r,i)=>{ const open=ZR.sys.progress.isUnlocked(r), here=tgt===r.id||(tgt==='gate'&&r.id==='city');
      return `<button class="isle ${open?'':'locked'} ${here?'target':''} ${r.id==='city'?'center':''}" data-region="${r.id}" style="--x:${r.x}%;--y:${r.y}%;--c:${r.color};--d:${i*.5}s">
        <img src="${r.img}" alt="" loading="lazy">${here?'<i class="marker">◈</i>':''}
        <div class="isle-lbl"><b>${open?ZR.L(r.name):ZR.t('unknown')}</b><small>${open?r.tag:'🔒 '+ZR.sys.progress.lockReason(r)}</small></div></button>`;}).join('')}
    <div class="fog f1"></div><div class="fog f2"></div>
   </div>${ZR.ui.objective()}</section>`; },

 games(){ const S=ZR.state.S;
  const places=['arcade','arena','ruins','archive'].map(ZR.data.region);
  return `<section class="scene"><div class="scene-title"><small>MINI-GAMES</small><h1>${ZR.lang()==='fa'?'بازی‌های قلمرو':'Games of the Realm'}</h1>
   <p>${ZR.lang()==='fa'?'هر بازی به مکانی از قلمرو تعلق دارد. برای بازی در میدان یا خرابه‌ها، ابتدا باید آن مکان را کشف کنی.':'Every game belongs to a place in the Realm. To play in the arena or ruins, you must first discover them.'}</p></div>
   ${ZR.ui.trialList(null)}
   ${places.map(r=>{ const open=ZR.sys.progress.isUnlocked(r);
    return `<div class="place ${open?'':'locked'}" style="--c:${r.color}"><div class="place-h"><img src="${r.img}"><div><small>${r.tag}</small><b>${ZR.L(r.name)}</b></div>${open?`<button class="btn-ghost sm" data-region="${r.id}">${ZR.t('enter')}</button>`:`<span class="lock-s">🔒 ${ZR.sys.progress.lockReason(r)}</span>`}</div>
     ${open?`<div class="glist">${r.games.map(g=>ZR.ui.gameCard(g,r.id)).join('')}</div>`:''}</div>`; }).join('')}
  </section>`; },

 quests(){ const S=ZR.state.S, all=Object.keys(ZR.data.quests), act=all.filter(k=>S.quests[k]?.status==='active'), done=all.filter(k=>S.quests[k]?.status==='done');
  const card=(k,d)=>{ const q=ZR.data.quests[k], p=!d&&ZR.sys.quests.progress(k), ch=ZR.data.chapterOf(k);
    return `<div class="quest ${d?'done':''} ${q.main?'main':''}" ${d?'':`data-go="${q.go}"`}><div class="q-ic">${d?'✔':q.main?'◈':'◇'}</div><div class="q-body">
     <small>${q.main?`CHAPTER ${ch.num} · ${ZR.t('mainQuest')}`:ZR.t('sideQuest')}</small><b>${ZR.L(q.title)}</b><p>${ZR.L(d&&q.reveal?q.reveal:q.desc)}</p>
     ${p?`<div class="qbar"><i style="width:${p[0]/p[1]*100}%"></i><em>${ZR.n(p[0])}/${ZR.n(p[1])}</em></div>`:''}
     ${d?'':`<div class="q-rw">🪙 ${ZR.n(q.reward.coins)} · ✨ ${ZR.n(q.reward.xp)}${q.reward.item?' · '+ZR.data.items[q.reward.item].icon:''}</div>`}</div></div>`; };
  return `<section class="scene"><div class="scene-title"><small>JOURNAL</small><h1>${ZR.t('journal')}</h1></div>
   <button class="codex-btn" data-act="codex"><span>📚</span><div><b>${ZR.t('codexT')}</b><small>${ZR.t('characters')} · ${ZR.t('locations')} · ${ZR.t('artifacts')} · ${ZR.t('loreT')}</small></div><em>${ZR.n(S.lore.length)}/${ZR.n(Object.keys(ZR.data.lore).length)}</em></button>
   ${ZR.ui.episodeBanner(true)}${ZR.ui.loopsPanel()}<h3 class="sec">${ZR.t('active')}</h3>${act.map(k=>card(k)).join('')||`<p class="muted">${ZR.lang()==='fa'?'فعلاً مأموریتی نداری. ادامه‌ی داستان به‌زودی…':'No quests right now. The story continues soon…'}</p>`}
   <h3 class="sec">${ZR.t('chapters')}</h3><div class="chaps">${ZR.ui.chapterList()}</div>
   ${done.length?`<h3 class="sec">${ZR.t('completed')}</h3>${done.slice().reverse().map(k=>card(k,1)).join('')}`:''}</section>`; },

 profile(){ const S=ZR.state.S, need=ZR.sys.progress.need(S.lv), inv=Object.entries(S.inv).filter(([,v])=>v>0);
  const ch=[]; if(S.choices.trustGuard!=null) ch.push(S.choices.trustGuard?T("به آذر اعتماد کردی.","You trusted Azar."):T("به آذر شک کردی.","You doubted Azar."));
  if(S.flags.rumor) ch.push(T("شایعه‌ی بهمن را خریدی.","You bought Bahman's rumor."));
  if(S.choices.trustShadow!=null) ch.push(S.choices.trustShadow?T("از چهره‌ی پنهان راه خواستی.","You asked the Veiled One for guidance."):T("به چهره‌ی پنهان اعتماد نکردی.","You refused to trust the Veiled One."));
  return `<section class="scene"><div class="prof">
    <img src="${ZR.ui.av(S.avatar)}" style="border-color:${ZR.ui.frame()};box-shadow:0 0 30px ${ZR.ui.frame()}">
    <h1>${S.name}</h1><div class="muted">${ZR.t('playerOf')} · ${ZR.t('lv')} ${ZR.n(S.lv)} · ${ZR.n(S.xp)}/${ZR.n(need)} ${ZR.t('xp')}</div><div class="xpb big"><i style="width:${S.xp/need*100}%"></i></div></div>
   <div class="stats">${[['played',S.stats.played],['wins',S.stats.wins],['lore',S.lore.length],['regions',S.visited.length]].map(([k,v])=>`<div><b>${ZR.n(v)}</b><small>${ZR.t(k)}</small></div>`).join('')}</div>
   <h3 class="sec">${ZR.t('path')}</h3>
   <div class="path">${ZR.data.milestones.map(m=>`<div class="ms ${S.lv>=m.lv?'on':''}"><span>${S.lv>=m.lv?m.icon:'🔒'}</span><div><small>${ZR.t('lv')} ${ZR.n(m.lv)}</small><b>${ZR.L(m.t)}</b></div></div>`).join('')}</div>
   <h3 class="sec">${ZR.t('inventory')}</h3>
   <div class="inv">${inv.length?inv.map(([k,v])=>{const it=ZR.data.items[k];return `<button class="slot-i ${it.story?'story':''}" data-item="${k}"><span>${it.icon}</span>${v>1?`<em>${ZR.n(v)}</em>`:''}<small>${ZR.L(it.name)}</small></button>`;}).join(''):`<p class="muted">${ZR.t('empty')}</p>`}</div>
   ${ch.length?`<h3 class="sec">${ZR.t('choicesT')}</h3><div class="choices-log">${ch.map(c=>`<p>◇ ${ZR.L(c)}</p>`).join('')}</div>`:''}
   <h3 class="sec">${ZR.t('achievements')} <em>${ZR.n(S.ach.length)}/${ZR.n(ZR.data.achievements.length)}</em></h3>
   <div class="achs">${ZR.data.achievements.map(a=>`<div class="ach ${S.ach.includes(a.id)?'got':''}"><span>${S.ach.includes(a.id)?a.icon:'🔒'}</span><b>${ZR.L(a.name)}</b><small>${ZR.L(a.desc)}</small></div>`).join('')}</div>
   <h3 class="sec">${ZR.t('settings')}</h3>
   <div class="set">
    <label>${ZR.t('name')}<div class="row"><input id="rn" maxlength="16" value="${S.name}"><button class="btn-ghost sm" data-act="rename">${ZR.t('save')}</button></div></label>
    <div class="avs sm">${ZR.data.avatars.map(a=>`<button data-setav="${a.id}" class="${S.avatar===a.id?'on':''}"><img src="${ZR.ui.av(a.id)}"></button>`).join('')}</div>
    <div class="toggles"><button data-act="lang">🌐 ${ZR.t('language')}: ${ZR.lang()==='fa'?'فارسی':'English'}</button>
     <button data-act="sfx">🔊 ${ZR.t('sound')}: ${S.settings.snd?'✓':'✗'}</button><button data-act="mus">🎵 ${ZR.t('music')}: ${S.settings.mus?'✓':'✗'}</button></div>
    <button class="btn-ghost danger" data-act="reset">${ZR.t('reset')}</button>
   </div>
   <div class="sign"><img src="assets/logo.webp"><span>ZHARFA STUDIO</span></div></section>`; }
};
ZR.ui.gameCard = (id,region) => { const g=ZR.games[id], S=ZR.state.S, lock=S.lv<(g.minLv||1), b=S.stats.best[id];
  return `<button class="gcard ${lock?'locked':''}" data-play="${id}" data-region="${region}" style="--c:${g.color}"><span class="g-ic">${lock?'🔒':g.icon}</span>
   <div><b>${ZR.L(g.name)}</b><small>${lock?`${ZR.t('gameLocked')} ${ZR.n(g.minLv)}`:ZR.L(g.desc)}</small>${b!=null?`<em>${ZR.t('record')}: ${ZR.n(b)}</em>`:''}</div><i>${ZR.t('play')}</i></button>`; };

;
/* Region view: art, description, inhabitants, games of this place, exploration, shop, trophies. */
ZR.ui.openRegion = id => {
  const r=ZR.data.region(id), S=ZR.state.S;
  if(!ZR.sys.progress.isUnlocked(r)){ ZR.sfx('lose'); ZR.ui.toast(`🔒 ${ZR.L(r.name)} — ${ZR.sys.progress.lockReason(r)}`); return; }
  ZR.ui.sheet.close();
  if(id==='city'){ if(ZR.ui.tab!=='home') ZR.ui.go('home'); else ZR.ui.overlay.close(); return; }
  if(!S.visited.includes(id)){ S.visited.push(id); ZR.state.save(); }
  ZR.audio.setMood(r.mood);
  const npcs=ZR.data.regionNpcs(r), qs=ZR.sys.quests.active().filter(k=>ZR.data.quests[k].go===id);
  const canSearch=r.search&&(!r.search.needQuest||S.quests[r.search.needQuest]);
  ZR.ui.overlay.open(`<div class="region" style="--c:${r.color}">
    ${ZR.ui.backBar(ZR.L(r.name), r.tag)}
    <div class="r-art ${r.id}"><img src="${r.img}" alt=""><div class="r-glow"></div>${r.id==='mystic'?'<div class="r-fog"></div>':''}</div>
    <p class="r-desc">${ZR.L(r.desc)}</p>
    ${qs.map(k=>`<div class="sheet-quest"><small>📜 ${ZR.t('questLine')}</small><b>${ZR.L(ZR.data.quests[k].title)}</b><p>${ZR.L(ZR.data.quests[k].desc)}</p></div>`).join('')}
    ${npcs.length?`<h3 class="sec">${ZR.t('people')}</h3><div class="npcs">${npcs.map(ZR.ui.npcChip).join('')}</div>`:''}
    ${ZR.ui.trialList(id)}${r.games.length?`<h3 class="sec">${ZR.t('gamesAt')}</h3><div class="glist">${r.games.map(g=>ZR.ui.gameCard(g,id)).join('')}</div>`:''}
    ${r.shop?ZR.ui.shop():''}
    ${r.trophies?ZR.ui.trophies():''}
    ${r.codex?`<h3 class="sec">${ZR.t('codexT')}</h3><button class="codex-btn" data-act="codex"><span>📚</span><div><b>${ZR.t('openCodex')}</b><small>${ZR.t('characters')} · ${ZR.t('locations')} · ${ZR.t('artifacts')} · ${ZR.t('loreT')} · ${ZR.t('chapters')}</small></div><em>${ZR.n(S.lore.length)}/${ZR.n(Object.keys(ZR.data.lore).length)}</em></button>`:''}
    ${canSearch?`<h3 class="sec">${ZR.t('explore')}</h3><button class="act" data-search="${id}"><span>🔍</span><div><b>${ZR.t('search')}</b><small>${S.searched.includes(id)?ZR.t('searched'):(ZR.lang()==='fa'?'سنگ‌ها و سایه‌ها را بکاو…':'Examine stones and shadows…')}</small></div></button>`:''}
  </div>`,'region-ov');
  ZR.ui.currentRegion=id;
  if(!ZR.ui._silent) ZR.bus.emit('visit',id);
};
ZR.ui.search = id => { const S=ZR.state.S, r=ZR.data.region(id), s=r.search;
  if(S.searched.includes(id)){ ZR.ui.toast(ZR.t('searched')); return; }
  S.searched.push(id); ZR.state.save(); ZR.sfx('mystery'); ZR.ui.sheet.close();
  const it=s.item&&ZR.data.items[s.item];
  ZR.sys.progress.addLore(s.lore);
  ZR.ui.readLore(s.lore, it?`${it.icon} ${ZR.L(it.name)}`:'', ()=>{ ZR.sys.progress.grant({coins:s.coins||0,xp:25}); if(s.item) ZR.act.give(s.item); ZR.bus.emit('search',id); });
};
ZR.ui.readLore = (k, extra='', after) => { const l=ZR.data.lore[k], d=ZR.$('#dialog'); d.className='on center';
  d.innerHTML=`<div class="lore-card fadein"><div class="lore-seal">📜</div><small>${extra?ZR.t('found'):ZR.t('codexT')}</small><h2>${ZR.L(l.title)}</h2><p>${ZR.L(l.text)}</p>${extra?`<div class="lore-item">+ ${extra}</div>`:''}<div class="dlg-next">${ZR.t('tapContinue')}</div></div>`;
  d.onclick=()=>{ d.className=''; d.innerHTML=''; d.onclick=null; after&&after(); ZR.ui.refresh(); }; };
ZR.ui.refresh = () => { const o=ZR.$('#overlay');
  if(o.classList.contains('region-ov') && ZR.ui.currentRegion){ const sc=o.scrollTop; ZR.ui._silent=true; ZR.ui.openRegion(ZR.ui.currentRegion); ZR.ui._silent=false; o.scrollTop=sc; }
  else if(o.classList.contains('codex-ov')){ /* keep */ }
  else if(!o.classList.contains('on')) ZR.ui.render();
  if(ZR.state.S.name){ ZR.ui.hud(); ZR.ui.nav(); } };

ZR.ui.shop = () => { const S=ZR.state.S;
  return `<h3 class="sec">${ZR.lang()==='fa'?'کالاها':'Wares'}</h3><div class="shop">${Object.entries(ZR.data.items).filter(([,i])=>i.price).map(([k,i])=>{const lock=i.lv&&S.lv<i.lv;
    return `<div class="ware"><span>${i.icon}</span><div><b>${ZR.L(i.name)}</b><small>${ZR.L(i.desc)}</small></div>${lock?`<button class="btn-ghost sm" disabled>🔒 ${ZR.t('lv')} ${ZR.n(i.lv)}</button>`:`<button class="btn-gold sm" data-buy="${k}">🪙 ${ZR.n(i.price)}</button>`}</div>`;}).join('')}</div>
   <h3 class="sec">${ZR.t('frames')}</h3><div class="shop">${ZR.data.frames.map(f=>{const own=(S.flags.frames||['none']).includes(f.id),eq=S.frame===f.id,lock=f.lv&&S.lv<f.lv;
    return `<div class="ware"><img src="${ZR.ui.av(S.avatar)}" style="border-color:${f.c};box-shadow:0 0 12px ${f.c}"><div><b>${ZR.L(f.name)}</b></div>${eq?`<button class="btn-ghost sm" disabled>${ZR.t('equipped')}</button>`:own?`<button class="btn-ghost sm" data-frame="${f.id}">${ZR.t('equip')}</button>`:lock?`<button class="btn-ghost sm" disabled>🔒 ${ZR.t('lv')} ${ZR.n(f.lv)}</button>`:`<button class="btn-gold sm" data-buyframe="${f.id}">🪙 ${ZR.n(f.p)}</button>`}</div>`;}).join('')}</div>`; };
ZR.ui.trophies = () => { const S=ZR.state.S;
  return `<h3 class="sec">${ZR.lang()==='fa'?'رکوردهای تو':'Your records'}</h3><div class="glist">${Object.values(ZR.games).map(g=>`<div class="gcard static" style="--c:${g.color}"><span class="g-ic">${g.icon}</span><div><b>${ZR.L(g.name)}</b><small>${S.stats.best[g.id]!=null?ZR.t('record')+': '+ZR.n(S.stats.best[g.id]):'—'} · ${ZR.n(S.stats.byGame[g.id]||0)}×</small></div></div>`).join('')}</div>
   <h3 class="sec">${ZR.t('achievements')}</h3><div class="achs">${ZR.data.achievements.map(a=>`<div class="ach ${S.ach.includes(a.id)?'got':''}"><span>${S.ach.includes(a.id)?a.icon:'🔒'}</span><b>${ZR.L(a.name)}</b><small>${ZR.L(a.desc)}</small></div>`).join('')}</div>`; };

;
/* UI for episodes, daily/weekly quests, tiers and trials. */
const _fa = () => ZR.lang()==='fa';

/* ───── Episode banner (home + journal) ───── */
ZR.ui.episodeBanner = (full) => { if(!ZR.state.S.name) return ''; const st=ZR.sys.episodes.status(), tot=ZR.data.EPISODES_TOTAL;
  const head=`<small>EPISODE ${ZR.n(st.n)} / ${ZR.n(tot)}</small>`;
  if(st.kind==='active') return full?`<div class="epb active">${head}<b>${ZR.L(st.e.t)}</b></div>`:'';
  if(st.kind==='wait') return `<div class="epb wait">${head}<b>⏳ ${ZR.L(st.e.t)}</b>
     <p>${_fa()?'اپیزود بعد':'Next episode in'} <em class="ep-count" data-ms="${Date.now()+st.ms}">${ZR.sys.episodes.fmt(st.ms)}</em> ${_fa()?'دیگر باز می‌شود':''}</p>
     <p class="muted">${_fa()?'تا آن موقع: مأموریت‌های روزانه، آزمون‌ها و درجه‌های سخت‌تر.':'Meanwhile: daily quests, trials and harder tiers.'}</p>
     ${full?'':`<button class="btn-ghost sm" data-tab="quests">📅 ${_fa()?'مأموریت‌های روزانه':'Daily quests'}</button>`}</div>`;
  if(st.kind==='level') return `<div class="epb level">${head}<b>🔒 CHAPTER ${st.ch.num} · ${ZR.L(st.ch.title)}</b>
     <p>${_fa()?`این فصل از سطح ${ZR.n(st.need)} باز می‌شود. سطح تو: ${ZR.n(ZR.state.S.lv)}`:`This chapter opens at level ${st.need}. You are level ${ZR.state.S.lv}.`}</p>
     <p class="muted">${_fa()?'با بازی، آزمون‌ها و مأموریت‌های روزانه تجربه جمع کن.':'Earn XP from games, trials and daily quests.'}</p></div>`;
  if(st.kind==='end') return `<div class="epb end"><small>CHAPTER III</small><b>${_fa()?'هفت نگهبان — به‌زودی':'The Seven Wardens — coming soon'}</b>
     <p class="muted">${_fa()?'ستاره‌ی سیاه صدا می‌زند… تا آن زمان قوی‌تر شو.':'The black star is calling… grow stronger until then.'}</p></div>`;
  return ''; };
ZR.ui.tickEpisode = () => ZR.$$('.ep-count').forEach(e=>{ const ms=+e.dataset.ms-Date.now(); if(ms<=0){ ZR.ui.refresh(); return; } e.textContent=ZR.sys.episodes.fmt(ms); });

ZR.ui.episodeCard = (n,e) => ZR.ui.cutscene({key:'ep'+n, bg:'assets/sky.webp', sfx:'unlock', mood:'story', hold:2400, lines:[
  {fa:`EPISODE ${n}`,en:`EPISODE ${n}`,cls:'tag'}, e.t,
  ...(ZR.sys.episodes.chapter(e).quests[0]===e.q[0] ? [{fa:`CHAPTER ${ZR.sys.episodes.chapter(e).num}`,en:`CHAPTER ${ZR.sys.episodes.chapter(e).num}`,cls:'tag'}, ZR.sys.episodes.chapter(e).title] : [])]});

/* ───── Daily / weekly panel ───── */
ZR.ui.loopsPanel = () => { const D=ZR.sys.daily.get(), W=ZR.state.S.weekly, dq=ZR.sys.daily;
  const row=(q,c,claimed,attr,rw)=>{ const p=dq.prog(q,c), ok=p>=q.n;
    return `<div class="lq ${claimed?'done':ok?'ready':''}"><div class="lq-b"><b>${ZR.L(q.t)}</b><div class="qbar"><i style="width:${p/q.n*100}%"></i><em>${ZR.n(p)}/${ZR.n(q.n)}</em></div></div>
      ${claimed?'<span class="lq-ok">✔</span>':`<button class="${ok?'btn-gold':'btn-ghost'} sm" ${ok?attr:'disabled'}>🪙${ZR.n(rw.coins)} ✨${ZR.n(rw.xp)}</button>`}</div>`; };
  const midnight=new Date(); midnight.setHours(24,0,0,0);
  const all=D.ids.every(i=>D.claimed.includes(i));
  return `<h3 class="sec">📅 ${_fa()?'مأموریت‌های روزانه':'Daily quests'} <em class="muted">${_fa()?'تازه‌سازی':'resets in'} <span class="ep-count" data-ms="${midnight.getTime()}">${ZR.sys.episodes.fmt(midnight-Date.now())}</span></em></h3>
   <div class="lqs">${D.ids.map(id=>{const q=dq.quest(id); return q?row(q,D.c,D.claimed.includes(id),`data-dclaim="${id}"`,dq.scale(q.rw)):'';}).join('')}
    <div class="lq chest ${all?'done':''}"><span>🎁</span><div class="lq-b"><b>${_fa()?'صندوق روزانه':'Daily chest'}</b><small>${_fa()?'با کامل کردن هر سه مأموریت':'Complete all three'} · 🪙${ZR.n(ZR.data.dailyBonus.coins)} ✨${ZR.n(ZR.data.dailyBonus.xp)} 🧪</small></div>${all?'<span class="lq-ok">✔</span>':''}</div></div>
   <h3 class="sec">🌙 ${_fa()?'اهداف هفتگی':'Weekly goals'}</h3>
   <div class="lqs">${ZR.data.weeklyGoals.map(q=>row(q,W.c,W.claimed.includes(q.id),`data-wclaim="${q.id}"`,dq.scale(q.rw))).join('')}</div>`; };

/* ───── Trials ───── */
ZR.ui.trialList = regionId => { const S=ZR.state.S, T=ZR.sys.trials;
  const ids=T.available().filter(id=>!regionId||ZR.data.trials[id].region===regionId); if(!ids.length) return '';
  return `<h3 class="sec">🛡️ ${_fa()?'آزمون‌ها':'Trials'}</h3><div class="trials">${ids.map(id=>{ const t=ZR.data.trials[id], r=T.rec(id), rw=T.reward(id), st=T.stages(id);
    const wk=t.weekly&&T.weeklyDone();
    return `<button class="trial ${wk?'done':''}" data-trial="${id}"><span class="tr-ic">${t.icon}</span><div class="tr-b"><small>${ZR.L(t.by)}${r.clears?` · ✔ ×${ZR.n(r.clears)}`:''}</small><b>${ZR.L(t.name)}</b>
      <div class="tr-st">${st.map(([g,tier])=>`<i title="${ZR.L(ZR.games[g].name)}">${ZR.games[g].icon}<sub>${ZR.n(tier)}</sub></i>`).join('')}</div>
      <em>${wk?(_fa()?'این هفته کامل شد':'Cleared this week'):rw?`🪙${ZR.n(rw.coins)} ✨${ZR.n(rw.xp)}${rw.item?' '+ZR.data.items[rw.item].icon:''}${!r.clears&&!t.weekly?(_fa()?' · پاداش نخست':' · first clear'):''}`:''}</em></div></button>`; }).join('')}</div>`; };

ZR.ui.playTrial = (id, fromRegion) => { const t=ZR.data.trials[id], S=ZR.state.S, stages=ZR.sys.trials.stages(id); let k=0;
  const r=ZR.data.region(t.region); ZR.ui.sheet.close(); ZR.audio.setMood(t.region==='arena'?'arena':'story');
  const box=ZR.ui.overlay.open(`${ZR.ui.backBar(`${t.icon} ${ZR.L(t.name)}`, ZR.L(t.by))}<div class="tr-dots">${stages.map((_,i)=>`<i data-i="${i}"></i>`).join('')}</div><div class="game-stage trial-stage"><div class="game"></div></div>`,'game-ov');
  ZR.ui.gameRegion = fromRegion ? t.region : null; ZR.ui._fromRegion=!!fromRegion;
  const el=box.querySelector('.game');
  const dots=()=>box.querySelectorAll('.tr-dots i').forEach((d,i)=>d.className=i<k?'ok':i===k?'on':'');
  const intro=()=>{ dots(); const [g,tier]=stages[k], G=ZR.games[g];
    el.innerHTML=`<div class="tr-intro fadein"><small>${_fa()?`مرحله‌ی ${ZR.n(k+1)} از ${ZR.n(stages.length)}`:`Stage ${k+1} of ${stages.length}`}</small><div class="tr-big">${G.icon}</div><h2>${ZR.L(G.name)}</h2>
      <p>${ZR.L(G.desc)}</p><p class="tier-tag">${'✦'.repeat(tier)} ${ZR.L(ZR.data.tiers[tier-1].name)}</p>
      ${k===0?`<p class="muted">${ZR.L(t.desc)} ${_fa()?'یک شکست = پایان آزمون.':'One loss ends the trial.'}</p>`:''}<button class="btn-gold big" id="trGo">${_fa()?'آغاز':'Begin'}</button></div>`;
    el.querySelector('#trGo').onclick=()=>{ ZR.sfx('choice'); run(); }; };
  const run=()=>{ const [g,tier]=stages[k]; el.innerHTML='';
    ZR.games[g].play(el,{ tier, end:res=>{ S.stats.played++; if(res.win) S.stats.wins++; S.stats.byGame[g]=(S.stats.byGame[g]||0)+1; ZR.state.save();
      ZR.bus.emit('game',{id:g,win:res.win,region:t.region,tier,trial:id});
      if(!res.win) return fail();
      ZR.sfx('win'); k++; if(k>=stages.length) return win();
      el.innerHTML=`<div class="result w"><div class="res-sigil">✦</div><h2>${_fa()?'مرحله گذشت':'Stage cleared'}</h2><div class="row-btns"><button class="btn-gold" id="trNext">${_fa()?'مرحله‌ی بعد':'Next stage'}</button></div></div>`;
      dots(); el.querySelector('#trNext').onclick=intro; } }); };
  const fail=()=>{ ZR.sfx('lose'); el.innerHTML=`<div class="result l"><div class="res-sigil">☾</div><h2>${_fa()?'آزمون شکست خورد':'Trial failed'}</h2>
      <p class="res-lore">${_fa()?`تا مرحله‌ی ${ZR.n(k+1)} از ${ZR.n(stages.length)} پیش رفتی.`:`You reached stage ${k+1} of ${stages.length}.`}</p>
      <div class="row-btns"><button class="btn-gold" id="trRe">${ZR.t('again')}</button><button class="btn-ghost" data-act="back">${ZR.t('back')}</button></div></div>`;
    const rec=ZR.sys.trials.rec(id); rec.best=Math.max(rec.best||0,k); ZR.state.save();
    el.querySelector('#trRe').onclick=()=>ZR.ui.playTrial(id,fromRegion); };
  const win=()=>{ dots(); const {rw,first}=ZR.sys.trials.clear(id); ZR.sfx('quest');
    el.innerHTML=`<div class="result w"><div class="res-sigil">🛡️</div><h2>${_fa()?'آزمون کامل شد':'Trial complete'}</h2>
      <p class="res-lore">${first?(_fa()?'نامت در سنگ‌های آزمون حک شد.':'Your name is carved into the trial stones.'):(_fa()?'هسته دوباره پاسخ داد.':'The Core answered again.')}</p>
      ${rw?`<div class="res-rw"><span>🪙 +${ZR.n(rw.coins)}</span><span>✨ +${ZR.n(rw.xp)}</span>${rw.item?`<span>${ZR.data.items[rw.item].icon}</span>`:''}</div>`:''}
      <div class="row-btns"><button class="btn-ghost" data-act="back">${ZR.t('back')}</button></div></div>`;
    if(rw&&rw.item) ZR.act.give(rw.item); };
  intro(); };

/* ───── Extra scenes ───── */
ZR.ui.scenes.ch2end = () => ZR.ui.cutscene({key:'ch2end', bg:'assets/sky.webp', sfx:'shadow', hold:3200, lines:[
  {fa:"CHAPTER II",en:"CHAPTER II",cls:'tag'}, T("ردپای هسته — کامل شد","Trace of the Core — complete"),
  T("بالای شهر، هسته برای اولین بار نامی را زمزمه کرد… نام یک نگهبان.","Above the city, for the first time, the Core whispered a name… the name of a Warden."),
  T("ستاره‌ی سیاه بیدار شده است.","The black star has awakened.")]}).then(()=>ZR.ui.comingSoon());

/* ───── Input ───── */
document.addEventListener('click', e => { const t=e.target.closest('[data-trial],[data-dclaim],[data-wclaim]');
  if(!t || t.closest('#dialog') || t.closest('#cutscene')) return; const d=t.dataset;
  if(d.trial){ const inRegion=ZR.$('#overlay').classList.contains('region-ov'); return ZR.ui.playTrial(d.trial, inRegion); }
  if(d.dclaim) return ZR.sys.daily.claim(d.dclaim);
  if(d.wclaim) return ZR.sys.daily.claimW(d.wclaim); });
// hidden developer switch: tap the studio signature in Profile 7 times → removes the daily episode lock
let _devTaps=0, _devT=0;
document.addEventListener('click', e => { if(!e.target.closest('.sign')) return; const now=Date.now(); _devTaps = now-_devT<1500 ? _devTaps+1 : 1; _devT=now;
  if(_devTaps>=7){ _devTaps=0; const S=ZR.state.S; S.settings.dev=!S.settings.dev; ZR.state.save(); ZR.sfx('unlock');
    ZR.ui.toast(S.settings.dev?(_fa()?'🛠 حالت سازنده: قفل روزانه برداشته شد':'🛠 Dev mode: daily lock removed'):(_fa()?'🛠 حالت سازنده خاموش شد':'🛠 Dev mode off'),'teal');
    ZR.sys.episodes.advance(); ZR.ui.render(); } });

;
/* Boot + global input delegation. */
ZR.ui.applyDir = () => { document.documentElement.lang=ZR.lang(); document.documentElement.dir=ZR.lang()==='fa'?'rtl':'ltr';
  document.title = ZR.lang()==='fa' ? 'قلمرو گمشده | THE LOST REALM — ZHARFA STUDIO' : 'THE LOST REALM | قلمرو گمشده — ZHARFA STUDIO'; };
ZR.ui.render = () => { if(!ZR.state.S.name) return; ZR.ui.hud(); ZR.ui.nav();
  ZR.$('#screen').innerHTML=ZR.ui.screens[ZR.ui.tab](); document.body.dataset.tab=ZR.ui.tab; };
ZR.ui.go = tab => { ZR.ui.sheet.close(); ZR.ui.overlay.close(); ZR.ui.tab=tab; ZR.ui.render(); window.scrollTo(0,0); ZR.sfx('soft'); };
ZR.ui.enterWorld = first => { ZR.$('#hud').classList.remove('hidden'); ZR.$('#nav').classList.remove('hidden');
  ZR.ui.tab='home'; ZR.audio.setMood('city'); ZR.ui.render(); ZR.audio.startMusic();
  if(first){ const S=ZR.state.S;
    ZR.story.enqueue(()=>ZR.ui.scenes.arrival());
    ZR.story.enqueue(async()=>{ ZR.sys.quests.start('q01'); });
    ZR.story.enqueue(()=>ZR.ui.talk('guard'));
    ZR.story.enqueue(async()=>{ if(!S.visited.includes('city')){S.visited.push('city');ZR.state.save();} ZR.bus.emit('visit','city'); });
  } };

document.addEventListener('click', e => {
  const t=e.target.closest('[data-tab],[data-act],[data-region],[data-play],[data-talk],[data-search],[data-lore],[data-go],[data-buy],[data-buyframe],[data-frame],[data-item],[data-setav],[data-hs],[data-cx]');
  if(!t || t.closest('#intro') || t.closest('#dialog') || t.closest('#cutscene')) return;
  const S=ZR.state.S, d=t.dataset;
  if(d.hs) return ZR.ui.openHotspot(d.hs);
  if(d.cx) return ZR.ui.openCodex(d.cx);
  if(d.tab) return ZR.ui.go(d.tab);
  if(d.play) return ZR.ui.playGame(d.play, d.region);
  if(d.region) return ZR.ui.openRegion(d.region);
  if(d.talk) return ZR.ui.talk(d.talk);
  if(d.search) return ZR.ui.search(d.search);
  if(d.lore) return ZR.ui.readLore(d.lore);
  if(d.go){ const g=d.go; if(g==='world') return ZR.ui.go('world');
    if(g==='city'){ ZR.ui.go('home'); return setTimeout(()=>ZR.ui.openHotspot('plaza'),150); }
    if(g==='gate'){ ZR.ui.go('home'); return setTimeout(()=>ZR.ui.openHotspot('gate'),150); }
    const r=ZR.data.region(g); if(r && !ZR.sys.progress.isUnlocked(r)) return ZR.ui.toast(`🔒 ${ZR.L(r.name)} — ${ZR.sys.progress.lockReason(r)}`);
    return ZR.ui.openRegion(g); }
  if(d.buy){ const it=ZR.data.items[d.buy]; if(S.coins<it.price){ZR.sfx('lose');return ZR.ui.toast(ZR.t('noCoins'));}
    S.coins-=it.price; S.flags.bought=(S.flags.bought||0)+1; ZR.state.save(); ZR.act.give(d.buy); ZR.sfx('coin');
    ZR.bus.emit('buy',d.buy); ZR.sys.progress.checkAch(); return ZR.ui.refresh(); }
  if(d.buyframe){ const f=ZR.data.frames.find(x=>x.id===d.buyframe); if(S.coins<f.p){ZR.sfx('lose');return ZR.ui.toast(ZR.t('noCoins'));}
    S.coins-=f.p; S.flags.frames=[...(S.flags.frames||['none']),f.id]; S.frame=f.id; S.flags.bought=(S.flags.bought||0)+1; ZR.state.save(); ZR.sfx('coin'); ZR.bus.emit('buy',f.id); return ZR.ui.refresh(); }
  if(d.frame){ S.frame=d.frame; ZR.state.save(); ZR.sfx('soft'); return ZR.ui.refresh(); }
  if(d.setav){ S.avatar=d.setav; ZR.state.save(); ZR.sfx('soft'); return ZR.ui.render(); }
  if(d.item){ const it=ZR.data.items[d.item]; if(it.use){ S.inv[d.item]--; ZR.state.save(); ZR.sys.progress.grant(it.use); ZR.ui.toast(`${it.icon} +${ZR.n(it.use.xp)} ✨`,'gold'); ZR.ui.render(); }
    else ZR.ui.toast(`${it.icon} ${ZR.L(it.name)} — ${ZR.L(it.desc)}`); return; }
  switch(d.act){
    case 'back': if(ZR.$('#overlay').classList.contains('game-ov') && ZR.ui.gameRegion && ZR.ui.gameRegion!=='none'){ const r=ZR.ui.gameRegion; ZR.ui.gameRegion=null; if(ZR.ui._fromRegion) return ZR.ui.openRegion(r); } return ZR.ui.overlay.close();
    case 'sheetclose': return ZR.ui.sheet.close();
    case 'codex': ZR.ui.sheet.close(); return ZR.ui.openCodex('characters');
    case 'lang': S.settings.lang=ZR.lang()==='fa'?'en':'fa'; ZR.state.save(); ZR.ui.applyDir(); return ZR.ui.render();
    case 'snd': { const on=!(S.settings.snd||S.settings.mus); S.settings.snd=on; S.settings.mus=on; ZR.state.save(); on?ZR.audio.startMusic():ZR.audio.stopMusic(); return ZR.ui.refresh(); }
    case 'sfx': S.settings.snd=!S.settings.snd; ZR.state.save(); return ZR.ui.render();
    case 'mus': S.settings.mus=!S.settings.mus; ZR.state.save(); S.settings.mus?ZR.audio.startMusic():ZR.audio.stopMusic(); return ZR.ui.render();
    case 'rename': { const v=ZR.$('#rn').value.trim(); if(v){S.name=v;ZR.state.save();ZR.ui.render();ZR.ui.toast('✓');} return; }
    case 'reset': if(confirm(ZR.t('resetQ'))) ZR.state.reset(); return;
    case 'bless': if(Date.now()-S.lastBlessing<864e5){ZR.sfx('soft');return ZR.ui.toast('⛲ '+ZR.t('blessingWait'));}
      S.lastBlessing=Date.now(); ZR.state.save(); ZR.sfx('coin'); ZR.ui.toast(`⛲ ${ZR.t('blessing')} +${ZR.n(80)}🪙 +${ZR.n(30)}✨`,'gold'); ZR.sys.progress.grant({coins:80,xp:30}); ZR.ui.sheet.close(); return ZR.ui.render();
  }
});
// remember whether a game was launched from inside a region, so Back returns there
document.addEventListener('click',e=>{ const p=e.target.closest('[data-play]'); if(p) ZR.ui._fromRegion = ZR.$('#overlay').classList.contains('region-ov') || (ZR.ui._fromRegion && ZR.$('#overlay').classList.contains('game-ov')); },true);
document.addEventListener('keydown',e=>{ if(e.key==='Escape'){ ZR.ui.sheet.close(); ZR.ui.overlay.close(); } });
ZR.bus.on('state',()=>{ if(ZR.state.S.name && !ZR.$('#hud').classList.contains('hidden')){ ZR.ui.hud(); ZR.ui.nav(); } });

// ambient particles (very subtle)
(()=>{ const c=ZR.$('#fx'),x=c.getContext&&c.getContext('2d'); if(!x || matchMedia('(prefers-reduced-motion: reduce)').matches) return; let P=[]; const R=()=>{c.width=innerWidth;c.height=innerHeight;}; R(); addEventListener('resize',R);
  for(let i=0;i<(innerWidth<700?16:36);i++) P.push({x:Math.random()*innerWidth,y:Math.random()*innerHeight,r:Math.random()*1.5+.3,v:Math.random()*.22+.04,h:Math.random()<.55?'232,184,90':'63,224,208',p:Math.random()*6});
  let last=0; (function loop(t){ requestAnimationFrame(loop); if(document.hidden || t-last<33) return; last=t; x.clearRect(0,0,c.width,c.height); P.forEach(p=>{ p.y-=p.v*2; p.p+=.03; if(p.y<-5){p.y=c.height+5;p.x=Math.random()*c.width;}
    x.beginPath(); x.arc(p.x+Math.sin(p.p)*10,p.y,p.r,0,7); x.fillStyle=`rgba(${p.h},${.28+.28*Math.sin(p.p)})`; x.fill(); }); })(0); })();

// boot
ZR.ui.applyDir(); ZR.sys.quests.init(); ZR.sys.loops.init();
if(ZR.state.S.name){ ZR.sys.progress.checkUnlocks(); ZR.ui.enterWorld(false); ZR.sys.quests.startSides(); ZR.sys.episodes.advance();
  const resume=()=>{ZR.audio.startMusic();document.removeEventListener('pointerdown',resume);}; document.addEventListener('pointerdown',resume); }
else ZR.ui.intro();
